fun search(items: List<Int>, target: Int): Int {
    var steps = 0
    for (item in items) {
        steps++
        if (item == target) return steps
    }
    return steps
}
fun main() {
    println(search(listOf(3, 6, 1, 8), 3))
    println(search(listOf(3, 6, 1, 8), 8))
}
